use maho_omo_task::dag_status_row_format::{run_rows_with_options,DagRunRowsOptions};
use senpi_task::dag::{graph::{DagDefinition,DagNodeInput},manager::{create_dag_manager,DagManagerOptions,DagStartParams},store::{create_dag_file_store,DagStoreConfig,DagStoreOptions},types::{DagNodeState,DagNodeTarget,DagRunSnapshot}};
use std::sync::Arc;

fn snapshot()->(tempfile::TempDir,DagRunSnapshot){let root=tempfile::tempdir().expect("root");let store=create_dag_file_store(&DagStoreConfig::new(root.path()),DagStoreOptions::default()).expect("store");let manager=create_dag_manager(DagManagerOptions{store:Arc::new(store),new_run_id:Some(Arc::new(||"run".into())),now:Some(Arc::new(||1_000)),materialize_skills:None,settings:None});let definition=DagDefinition{key:"key".into(),name:"run".into(),nodes:vec![DagNodeInput{id:"node".into(),prompt:"work".into(),target:DagNodeTarget::Category("quick".into()),label:None,depends_on:None,task_summary:None,description:None,load_skills:None}]};let run=manager.start(DagStartParams{definition,parent_session_id:"parent".into(),root_session_id:"root".into()}).expect("start").snapshot;(root,run)}
#[test] fn running_nodes_are_sorted_first_and_never_lost_to_row_cap(){let(_root,mut run)=snapshot();let original=run.nodes[0].clone();run.nodes=(0..15).map(|index|{let mut node=original.clone();node.id=if index<12 {format!("p{index}")} else {format!("r{index}")};if index>=12 {node.state=DagNodeState::Running;node.started_at=Some(format!("2026-08-24T12:00:{:02}.000Z",index));}node}).collect();let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[1].contains("r12"));assert!(rows[3].contains("r14"));assert_eq!(rows.last().map(String::as_str),Some("  +3 more"));}
#[test] fn activity_obeys_width_and_nonterminal_state_and_elapsed_clock(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Pending;run.nodes[0].created_at="2026-08-24T11:59:00.000Z".into();let activity=std::collections::BTreeMap::from([("node".into(),"spawning child".into())]);let wide_options=DagRunRowsOptions{max_width:Some(120),now:Some(1_777_000_000_000),is_process_alive:None};let wide=run_rows_with_options(&run,Some(&activity),Some(&wide_options));assert!(wide[1].contains("spawning child"));assert!(wide[1].contains("waiting"));let narrow_options=DagRunRowsOptions{max_width:Some(50),..wide_options};let narrow=run_rows_with_options(&run,Some(&activity),Some(&narrow_options));assert!(!narrow[1].contains("spawning"));}
#[test] fn hours_and_unparseable_timestamps_use_the_ts_duration_contract(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Running;run.nodes[0].started_at=Some("2026-08-24T10:00:00.000Z".into());let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_572_800_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[1].contains("h"));run.nodes[0].started_at=Some("invalid".into());run.nodes[0].created_at="invalid".into();let rows=run_rows_with_options(&run,None,Some(&options));assert!(!rows[1].contains("waiting"));}
#[test] fn injected_process_probe_controls_paused_header(){let(_root,mut run)=snapshot();run.status=senpi_task::dag::types::DagRunStatus::Paused;run.lease_holder_pid=Some(4242);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_000_000_000),is_process_alive:Some(Arc::new(|pid|pid==4242))};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[0].starts_with("· "));assert!(rows[0].contains("resuming"));}
#[test] fn given_thirteen_running_nodes_then_all_running_rows_precede_capped_settled_rows(){let(_root,mut run)=snapshot();let original=run.nodes[0].clone();run.nodes=(0..15).map(|i|{let mut n=original.clone();n.id=format!("n{i}");n.state=if i<13{DagNodeState::Running}else{DagNodeState::Completed};n.started_at=Some(format!("2026-08-24T11:{:02}:00.000Z",i));n.completed_at=Some(format!("2026-08-24T11:{:02}:30.000Z",i));n}).collect();let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert_eq!(rows[1..].iter().filter(|row|row.contains("▶")).count(),13);assert!(rows.iter().all(|row|!row.contains("n13")&&!row.contains("n14")));assert_eq!(rows.last().map(String::as_str),Some("  +2 more"));}
#[test] fn given_equal_rank_equal_time_nodes_then_declaration_order_is_stable(){let(_root,mut run)=snapshot();let original=run.nodes[0].clone();let mut second=original.clone();second.id="second".into();run.nodes=vec![original,second];let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[1].contains("node"));assert!(rows[2].contains("second"));}
#[test] fn given_untimestamped_running_peer_then_it_sorts_after_timed_running_nodes(){let(_root,mut run)=snapshot();let mut timed=run.nodes[0].clone();timed.id="timed".into();timed.state=DagNodeState::Running;timed.started_at=Some("2026-08-24T11:00:00.000Z".into());let mut unknown=timed.clone();unknown.id="unknown".into();unknown.started_at=None;run.nodes=vec![unknown,timed];let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[1].contains("timed"));assert!(rows[2].contains("unknown"));}
#[test] fn given_terminal_nodes_then_completed_elapsed_freezes_and_waiting_is_absent(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Completed;run.nodes[0].started_at=Some("2026-08-24T10:00:00.000Z".into());run.nodes[0].completed_at=Some("2026-08-24T10:03:04.000Z".into());let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let settled=run_rows_with_options(&run,None,Some(&options));assert!(settled[1].contains("3m 4s"));run.nodes[0].state=DagNodeState::Skipped;run.nodes[0].started_at=None;run.nodes[0].completed_at=None;let skipped=run_rows_with_options(&run,None,Some(&options));assert!(!skipped[1].contains("waiting"));}
#[test] fn given_pending_node_with_created_at_then_waiting_label_advances_with_injected_clock(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Pending;run.nodes[0].created_at="2026-08-24T11:59:00.000Z".into();let first=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let later=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_618_000_000),is_process_alive:None};let one=run_rows_with_options(&run,None,Some(&first));let two=run_rows_with_options(&run,None,Some(&later));assert_ne!(one[1],two[1]);}
#[test] fn given_pre_running_states_then_icons_are_distinct(){let(_root,mut run)=snapshot();let original=run.nodes[0].clone();run.nodes=[DagNodeState::Pending,DagNodeState::Scheduled,DagNodeState::Blocked].into_iter().enumerate().map(|(i,state)|{let mut n=original.clone();n.id=format!("n{i}");n.state=state;n}).collect();let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));let glyphs=rows[1..].iter().map(|row|row.trim_start().chars().next().expect("icon")).collect::<std::collections::BTreeSet<_>>();assert_eq!(glyphs.len(),3);}
#[test] fn given_activity_on_settled_node_then_stale_activity_is_hidden(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Completed;run.nodes[0].started_at=Some("2026-08-24T10:00:00.000Z".into());run.nodes[0].completed_at=Some("2026-08-24T10:01:00.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"stale activity".into())]);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(!rows[1].contains("stale"));}
#[test] fn given_paused_run_with_stranded_running_nodes_then_header_reports_active_count(){let(_root,mut run)=snapshot();run.status=senpi_task::dag::types::DagRunStatus::Paused;let mut second=run.nodes[0].clone();second.id="second".into();run.nodes[0].state=DagNodeState::Running;second.state=DagNodeState::Running;run.nodes.push(second);let options=DagRunRowsOptions{max_width:Some(200),now:Some(1_787_588_000_000),is_process_alive:Some(Arc::new(|_|false))};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[0].starts_with("· "));assert!(rows[0].contains("suspended · 2 active"));}
#[test] fn given_dead_paused_lease_without_running_nodes_then_header_stays_paused(){let(_root,mut run)=snapshot();run.status=senpi_task::dag::types::DagRunStatus::Paused;run.lease_holder_pid=Some(4243);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:Some(Arc::new(|_|false))};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[0].starts_with("· "));assert!(rows[0].contains("paused"));assert!(!rows[0].contains("resuming"));}
#[test] fn given_row_width_under_activity_threshold_then_activity_drops_but_route_remains(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Running;run.nodes[0].started_at=Some("2026-08-24T11:59:15.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"running bash sleep command".into())]);let options=DagRunRowsOptions{max_width:Some(50),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(rows[1].contains("category:quick"));assert!(!rows[1].contains("sleep command"));assert!(rows[1].len()<=50);}
#[test] fn given_long_activity_and_wide_terminal_then_activity_receives_width_slack(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Running;run.nodes[0].started_at=Some("2026-08-24T11:59:48.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"inspecting the scheduler claim path and re-reading the wave manifest".into())]);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(rows[1].contains("inspecting the scheduler claim path"));assert!(rows[1].len()<=120);}
#[test] fn given_a_short_node_on_wide_terminal_then_row_is_not_padded(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Running;run.nodes[0].started_at=Some("2026-08-24T11:59:55.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"running bash".into())]);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(!rows[1].ends_with(' '));}
#[test] fn given_equal_recency_nodes_then_declaration_order_is_stable(){let(_root,mut run)=snapshot();let original=run.nodes[0].clone();let mut second=original.clone();second.id="second".into();run.nodes=vec![original,second];let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[1].contains("node"));assert!(rows[2].contains("second"));}
#[test] fn given_untimestamped_running_node_then_timed_sibling_sorts_first(){let(_root,mut run)=snapshot();let mut timed=run.nodes[0].clone();timed.id="timed".into();timed.state=DagNodeState::Running;timed.started_at=Some("2026-08-24T11:00:00.000Z".into());let mut untimed=timed.clone();untimed.id="untimed".into();untimed.started_at=None;run.nodes=vec![untimed,timed];let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[1].contains("timed"));assert!(rows[2].contains("untimed"));}
#[test] fn given_completed_node_then_elapsed_freezes_and_terminal_waiting_is_absent(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Completed;run.nodes[0].started_at=Some("2026-08-24T10:00:00.000Z".into());run.nodes[0].completed_at=Some("2026-08-24T10:03:04.000Z".into());let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let settled=run_rows_with_options(&run,None,Some(&options));assert!(settled[1].contains("3m 4s"));run.nodes[0].state=DagNodeState::Skipped;run.nodes[0].started_at=None;run.nodes[0].completed_at=None;let skipped=run_rows_with_options(&run,None,Some(&options));assert!(!skipped[1].contains("waiting"));}
#[test] fn given_pending_node_then_waiting_label_advances_with_injected_clock(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Pending;run.nodes[0].created_at="2026-08-24T11:59:00.000Z".into();let first=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let later=DagRunRowsOptions{now:Some(1_787_618_000_000),..DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None}};let one=run_rows_with_options(&run,None,Some(&first));let two=run_rows_with_options(&run,None,Some(&later));assert_ne!(one[1],two[1]);}
#[test] fn given_pending_scheduled_and_blocked_nodes_then_icons_are_distinct(){let(_root,mut run)=snapshot();let original=run.nodes[0].clone();run.nodes=[DagNodeState::Pending,DagNodeState::Scheduled,DagNodeState::Blocked].into_iter().enumerate().map(|(index,state)|{let mut node=original.clone();node.id=format!("n{index}");node.state=state;node}).collect();let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,None,Some(&options));let glyphs=rows[1..].iter().map(|row|row.trim_start().chars().next().expect("icon")).collect::<std::collections::BTreeSet<_>>();assert_eq!(glyphs.len(),3);}
#[test] fn given_terminal_node_with_stale_activity_then_activity_is_hidden(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Completed;run.nodes[0].started_at=Some("2026-08-24T10:00:00.000Z".into());run.nodes[0].completed_at=Some("2026-08-24T10:01:00.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"stale activity".into())]);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(!rows[1].contains("stale"));}
#[test] fn given_paused_run_with_running_nodes_then_header_reports_suspended_active_count(){let(_root,mut run)=snapshot();run.status=senpi_task::dag::types::DagRunStatus::Paused;run.nodes[0].state=DagNodeState::Running;let mut second=run.nodes[0].clone();second.id="second".into();run.nodes.push(second);let options=DagRunRowsOptions{max_width:Some(200),now:Some(1_787_588_000_000),is_process_alive:Some(Arc::new(|_|false))};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[0].starts_with("· "));assert!(rows[0].contains("suspended · 2 active"));}
#[test] fn given_paused_run_without_live_lease_or_running_nodes_then_header_stays_paused(){let(_root,mut run)=snapshot();run.status=senpi_task::dag::types::DagRunStatus::Paused;run.lease_holder_pid=Some(4243);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:Some(Arc::new(|_|false))};let rows=run_rows_with_options(&run,None,Some(&options));assert!(rows[0].starts_with("· "));assert!(rows[0].contains("paused"));assert!(!rows[0].contains("resuming"));}
#[test] fn given_row_width_under_activity_threshold_then_activity_drops_but_elapsed_and_route_remain(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Running;run.nodes[0].started_at=Some("2026-08-24T11:59:15.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"sleep command details".into())]);let options=DagRunRowsOptions{max_width:Some(50),now:Some(1_787_572_800_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(rows[1].contains("category:quick"));assert!(rows[1].contains("45s"));assert!(!rows[1].contains("sleep command"));assert!(rows[1].len()<=50);}
#[test] fn given_long_activity_and_wide_terminal_then_activity_receives_slack(){let(_root,mut run)=snapshot();run.nodes[0].state=DagNodeState::Running;run.nodes[0].started_at=Some("2026-08-24T11:59:48.000Z".into());let activity=std::collections::BTreeMap::from([("node".into(),"inspecting scheduler claim path and re-reading the wave manifest".into())]);let options=DagRunRowsOptions{max_width:Some(120),now:Some(1_787_588_000_000),is_process_alive:None};let rows=run_rows_with_options(&run,Some(&activity),Some(&options));assert!(rows[1].contains("inspecting scheduler claim path"));assert!(rows[1].len()<=120);}
